"use client";

import { useState, useEffect } from "react";
import { motion } from "framer-motion";
import {
  AiOutlineDashboard,
  AiOutlinePlus,
  AiOutlineShopping,
  AiOutlineMoneyCollect,
  AiOutlineSafety,
  AiOutlineTeam,
} from "react-icons/ai";
import { useRouter } from "next/navigation";
import { useSelector } from "react-redux";

export default function DynamicSidebar({ setSidebarWidth }: any) {
  const [isOpen, setIsOpen] = useState(true);
  const router = useRouter();

  const user = useSelector((state: any) => state.user.userData);
  const role = user?.role;

  const vendorMenu = [
    { icon: AiOutlineDashboard, label: "Dashboard", path: "/vendor/dashboard" },
    { icon: AiOutlinePlus, label: "Add Product", path: "/vendor/add-product" },
    { icon: AiOutlineShopping, label: "Orders", path: "/vendor/orders" },
    { icon: AiOutlineMoneyCollect, label: "Revenue", path: "/vendor/revenue" },
  ];

  const adminMenu = [
    { icon: AiOutlineDashboard, label: "Admin Dashboard", path: "/admin/dashboard" },
    { icon: AiOutlineSafety, label: "Check Permission", path: "/admin/permissions" },
    { icon: AiOutlineTeam, label: "Total Vendors", path: "/admin/vendors" },
  ];

  const menuItems = role === "admin" ? adminMenu : vendorMenu;

  const toggleSidebar = () => {
    setIsOpen(!isOpen);
    setSidebarWidth(!isOpen ? "16rem" : "4rem");
  };



  return (
    <motion.div
      animate={{ width: isOpen ? "16rem" : "4rem" }}
      transition={{ duration: 0.3 }}
      className="h-screen w-64 fixed top-0 left-0 bg-black text-white px-3  shadow-xl flex flex-col border-r py-[60px]"
    >
      {/* Toggle Button */}
      <button
        onClick={toggleSidebar}
        className="text-white text-2xl mb-6 px-2"
      >
        {isOpen ? "✖" : "☰"}
      </button>

      {/* Sidebar Menu */}
      <div className="flex flex-col gap-4 mt-2">
        {menuItems.map((item, idx) => (
          <button
            key={idx}
            onClick={() => router.push(item.path)}
            className="flex items-center gap-3 px-3 py-2 rounded-lg hover:bg-white/10 transition"
          >
            <item.icon size={24} />
            {isOpen && <span className="text-sm">{item.label}</span>}
          </button>
        ))}
      </div>
    </motion.div>
  );
}
